const config = {
  "previewFeatures": [],
  "clientVersion": "7.10.0",
  "engineVersion": "0edf323efd1d98336f3f0a68684b56f689b900d3",
  "activeProvider": "postgresql",
  "inlineSchema": "// ============================================================================\n// SCHEMA PRISMA - Sistema PWA de Evaluación Basada en Riesgo (EBR/BPM)\n// ============================================================================\n// Este archivo contiene DOS bloques:\n//\n//   [A] MODELOS YA EXISTENTES EN LA BD (tomados de diagrama0.json / Lucidchart)\n//       Se declaran para que Prisma pueda resolver las relaciones hacia ellos.\n//       Están marcados con el comentario \"// [EXISTENTE]\". Los campos marcados\n//       con \"// [NUEVO]\" dentro de estos modelos son columnas que HAY que\n//       agregar vía migración porque el SRS los pide y hoy no existen.\n//\n//   [B] MODELOS NUEVOS a crear, agrupados por el requerimiento (RF-xx) del SRS\n//       que cubren.\n//\n// Convención: nombres de tabla/columna en snake_case (igual que el ERD ya\n// creado), mapeados con @map/@@map para mantener estilo camelCase en Prisma.\n// ============================================================================\n\ngenerator client {\n  provider = \"prisma-client-js\"\n  output   = \"../src/generated/prisma\"\n  runtime  = \"nodejs\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n}\n\n// ============================================================================\n// [A] MODELOS EXISTENTES (referencia, extraídos de diagrama0.json)\n// ============================================================================\n\n/// [EXISTENTE] RF-01 / RF-02 - Persona física base (usuarios, propietarios, representantes)\nmodel Person {\n  personId Int    @id @default(autoincrement()) @map(\"person_id\")\n  name     String\n  cedula   String @unique\n  phone    String\n  email    String @unique\n\n  user       User?\n  propietary Propietary?\n  represents Represent[]\n\n  @@map(\"person\")\n}\n\n/// [EXISTENTE] RF-01 - Credenciales de acceso\n/// [NUEVO] roleId, status, campos de recuperación/2FA se agregan vía relaciones abajo (B.1)\nmodel User {\n  userId   Int    @id @default(autoincrement()) @map(\"user_id\")\n  personId Int    @unique @map(\"person_id\")\n  password String\n\n  // [NUEVO] necesarios para RF-01/RF-02/RNF-02\n  roleId    Int?       @map(\"role_id\")\n  status    UserStatus @default(PENDIENTE_VALIDACION) // [NUEVO]\n  isActive  Boolean    @default(true) @map(\"is_active\") // [NUEVO]\n  createdAt DateTime   @default(now()) @map(\"created_at\") // [NUEVO]\n\n  person              Person               @relation(fields: [personId], references: [personId])\n  role                Role?                @relation(fields: [roleId], references: [roleId])\n  passwordResets      PasswordResetToken[]\n  twoFactorAuth       TwoFactorAuth?\n  notifications       Notification[]\n  coordinatedCases    Case[]               @relation(\"CaseCoordinator\")\n  technicianCases     Case[]               @relation(\"CaseTechnician\")\n  assignmentsMade     Assignment[]         @relation(\"AssignedBy\")\n  assignmentsTaken    Assignment[]         @relation(\"AssignedTo\")\n  evaluationsRun      Evaluation[]         @relation(\"EvaluationTechnician\")\n  reviewsDone         ReportReview[]\n  attachmentsUploaded Attachment[]\n  bpmRequestsCreated  BpmRequest[]\n\n  @@map(\"user\")\n}\n\n/// [EXISTENTE] Dueño de una institución (empresa)\nmodel Propietary {\n  propietaryId Int @id @default(autoincrement()) @map(\"propietary_id\")\n  personId     Int @unique @map(\"person_id\")\n\n  person       Person        @relation(fields: [personId], references: [personId])\n  institutions Institution[]\n\n  @@map(\"propietary\")\n}\n\n/// [EXISTENTE] RF-03 - Representante de una empresa (legal / calidad / contacto)\n/// [NUEVO] institutionId + tipo: hoy solo enlaza a person; el SRS pide 3 tipos de\n/// representante por empresa (Legal, Calidad, Contacto principal).\nmodel Represent {\n  representId Int @id @default(autoincrement()) @map(\"represent_id\")\n  personId    Int @map(\"person_id\")\n\n  institutionId Int?           @map(\"institution_id\") // [NUEVO]\n  type          RepresentType? // [NUEVO] LEGAL | CALIDAD | CONTACTO\n\n  person        Person         @relation(fields: [personId], references: [personId])\n  institution   Institution?   @relation(fields: [institutionId], references: [institutionId])\n  formResponses FormResponse[]\n\n  @@map(\"represent\")\n}\n\n/// [EXISTENTE] RF-03 - Empresa / establecimiento\n/// [NUEVO] nombreComercial, actividadEconomica, municipalityId reemplazan los\n/// campos libres de municipio/provincia del SRS por catálogo normalizado.\nmodel Institution {\n  institutionId Int     @id @default(autoincrement()) @map(\"institution_id\")\n  name          String\n  streetName    String  @map(\"street_name\")\n  streetNum     String? @map(\"street_num\")\n  phoneNumber   String  @map(\"phone_number\")\n  email         String\n  rnc           String\n  propietaryId  Int     @map(\"propietary_id\")\n\n  // [NUEVO] campos pedidos en RF-03\n  nombreComercial    String? @map(\"nombre_comercial\")\n  actividadEconomica String? @map(\"actividad_economica\")\n  municipalityId     Int?    @map(\"municipality_id\")\n\n  propietary     Propietary          @relation(fields: [propietaryId], references: [propietaryId])\n  municipality   Municipality?       @relation(fields: [municipalityId], references: [municipalityId])\n  formResponses  FormResponse[]\n  status         InstitutionStatus[]\n  saPermits      SaPermit[]\n  representantes Represent[]\n  bpmRequests    BpmRequest[]\n  cases          Case[]\n  lapchAlerts    LapchAlert[]\n  complaints     Complaint[]\n  evaluations    Evaluation[]\n\n  @@map(\"institution\")\n}\n\n/// [EXISTENTE] Estado / certificación vigente de una institución\nmodel InstitutionStatus {\n  institutionStatusId Int      @id @default(autoincrement()) @map(\"institution_status_id\")\n  institutionId       Int      @map(\"institution_id\")\n  validUntil          DateTime @map(\"valid_until\")\n\n  institution Institution                 @relation(fields: [institutionId], references: [institutionId])\n  questions   InstitutionStatusQuestion[]\n\n  @@map(\"institution_status\")\n}\n\n/// [EXISTENTE]\nmodel InstitutionStatusQuestion {\n  institutionStatusQuestionId Int    @id @default(autoincrement()) @map(\"institution_status_question_id\")\n  institutionStatusId         Int    @map(\"institution_status_id\")\n  question                    String\n  type                        String\n  value                       String\n\n  institutionStatus InstitutionStatus @relation(fields: [institutionStatusId], references: [institutionStatusId])\n\n  @@map(\"institution_status_question\")\n}\n\n/// [EXISTENTE] Permiso Sanitario\nmodel SaPermit {\n  saPermitId     Int      @id @default(autoincrement()) @map(\"sa_permit_uuid\")\n  expiration     DateTime\n  formResponseId Int      @map(\"form_response_id\")\n  valid          Boolean\n  institutionId  Int      @map(\"institution_id\")\n\n  formResponse FormResponse @relation(fields: [formResponseId], references: [formResponseId])\n  institution  Institution  @relation(fields: [institutionId], references: [institutionId])\n\n  @@map(\"sa_permit\")\n}\n\n/// [EXISTENTE] Categoría de alimento\nmodel Category {\n  categoryId Int    @id @default(autoincrement()) @map(\"category_id\")\n  name       String\n\n  subCategories SubCategory[]\n  foods         Food[]\n\n  @@map(\"category\")\n}\n\n/// [EXISTENTE] RF-14 - Subcategoría con nivel de riesgo (Matriz_Riesgo_Alimentos.xlsx)\nmodel SubCategory {\n  subCategoryId Int    @id @default(autoincrement()) @map(\"sub_category_id\")\n  categoryId    Int    @map(\"category_id\")\n  name          String\n  risk          Int\n\n  category Category @relation(fields: [categoryId], references: [categoryId])\n\n  @@map(\"sub_category\")\n}\n\n/// [EXISTENTE]\nmodel Food {\n  foodId     Int    @id @default(autoincrement()) @map(\"food_id\")\n  name       String\n  categoryId Int    @map(\"category_id\")\n\n  category      Category       @relation(fields: [categoryId], references: [categoryId])\n  formResponses FormResponse[]\n\n  @@map(\"food\")\n}\n\n/// [EXISTENTE] Plantilla de ficha (ej. \"Ficha Inspección BPM v1.00\")\nmodel FormTemplate {\n  formTemplateId Int      @id @default(autoincrement()) @map(\"form_template_id\")\n  name           String\n  active         Boolean\n  createAt       DateTime @map(\"create_at\")\n  /// Null means this form applies to every case origin and establishment type.\n  /// Shape: { \"origins\"?: string[], \"establishmentTypes\"?: string[] }\n  appliesTo      Json?    @map(\"applies_to\")\n\n  h1s           H1[]\n  formResponses FormResponse[]\n\n  @@map(\"form_template\")\n}\n\n/// [EXISTENTE] RF-12/RF-13 - Ficha diligenciada (respuestas en JSONB)\nmodel FormResponse {\n  formResponseId Int      @id @default(autoincrement()) @map(\"form_response_id\")\n  name           String\n  createAt       DateTime @map(\"create_at\")\n  formTemplateId Int      @map(\"form_template_id\")\n  institutionId  Int      @map(\"institution_id\")\n  representId    Int      @map(\"represent_id\")\n  foodId         Int      @map(\"food_id\")\n  motive         String\n  answers        Json\n\n  formTemplate FormTemplate @relation(fields: [formTemplateId], references: [formTemplateId])\n  institution  Institution  @relation(fields: [institutionId], references: [institutionId])\n  represent    Represent    @relation(fields: [representId], references: [representId])\n  food         Food         @relation(fields: [foodId], references: [foodId])\n  saPermits    SaPermit[]\n  evaluation   Evaluation?\n  bpmRequest   BpmRequest?\n\n  @@map(\"form_response\")\n}\n\n/// [EXISTENTE] Nivel 1 de la jerarquía de la ficha (ej. \"1. ESTABLECIMIENTO\")\nmodel H1 {\n  h1Id           Int    @id @default(autoincrement()) @map(\"h1_id\")\n  name           String\n  formId         Int    @map(\"form_id\")\n  formTemplateId Int    @map(\"form_template_id\")\n  /// Null means this chapter is required for every case that uses the template.\n  /// Shape: { \"origins\"?: string[], \"establishmentTypes\"?: string[] }\n  appliesTo      Json?  @map(\"applies_to\")\n\n  formTemplate FormTemplate @relation(fields: [formTemplateId], references: [formTemplateId])\n  h1Asks       H1Ask[]\n  h2s          H2[]\n\n  @@map(\"h1\")\n}\n\n/// [EXISTENTE]\nmodel H1Ask {\n  h1AskId Int     @id @default(autoincrement()) @map(\"h1_ask_id\")\n  name    String\n  h1Id    Int     @map(\"h1_id\")\n  active  Boolean\n\n  h1 H1 @relation(fields: [h1Id], references: [h1Id])\n\n  @@map(\"h1_ask\")\n}\n\n/// [EXISTENTE] Nivel 2 (ej. \"1.1 Ubicación y estructura\")\nmodel H2 {\n  h2Id Int    @id @default(autoincrement()) @map(\"h2_id\")\n  h1Id Int    @map(\"h1_id\")\n  name String\n\n  h1     H1      @relation(fields: [h1Id], references: [h1Id])\n  h2Asks H2Ask[]\n  h3s    H3[]\n\n  @@map(\"h2\")\n}\n\n/// [EXISTENTE]\nmodel H2Ask {\n  h2AskId Int     @id @default(autoincrement()) @map(\"h2_ask_id\")\n  name    String\n  h2Id    Int     @map(\"h2_id\")\n  active  Boolean\n\n  h2 H2 @relation(fields: [h2Id], references: [h2Id])\n\n  @@map(\"h2_ask\")\n}\n\n/// [EXISTENTE] Nivel 3 (ej. \"1.1.1 Ubicación del establecimiento\")\nmodel H3 {\n  h3Id Int    @id @default(autoincrement()) @map(\"h3_id\")\n  h2Id Int    @map(\"h2_id\")\n  name String\n\n  h2     H2      @relation(fields: [h2Id], references: [h2Id])\n  h3Asks H3Ask[]\n  h4s    H4[]\n\n  @@map(\"h3\")\n}\n\n/// [EXISTENTE]\nmodel H3Ask {\n  h3AskId Int     @id @default(autoincrement()) @map(\"h3_ask_id\")\n  name    String\n  h3Id    Int     @map(\"h3_id\")\n  active  Boolean\n\n  h3 H3 @relation(fields: [h3Id], references: [h3Id])\n\n  @@map(\"h3_ask\")\n}\n\n/// [EXISTENTE] Nivel 4 (ej. \"1.1.3.1 Paredes\")\nmodel H4 {\n  h4Id Int    @id @default(autoincrement()) @map(\"h4_id\")\n  h3Id Int    @map(\"h3_id\")\n  name String\n\n  h3     H3      @relation(fields: [h3Id], references: [h3Id])\n  h4Asks H4Ask[]\n\n  @@map(\"h4\")\n}\n\n/// [EXISTENTE]\nmodel H4Ask {\n  h4AskId Int     @id @default(autoincrement()) @map(\"h4_ask_id\")\n  name    String\n  h4Id    Int     @map(\"h4_id\")\n  active  Boolean\n\n  h4 H4 @relation(fields: [h4Id], references: [h4Id])\n\n  @@map(\"h4_ask\")\n}\n\n/// [EXISTENTE] Bitácora de cambios sobre una pregunta (h_id genérico + h_num)\nmodel AskAuditory {\n  askAuditoryId Int      @id @default(autoincrement()) @map(\"ask_auditory_id\")\n  hId           String   @map(\"h_id\")\n  hNum          Int      @map(\"h_num\")\n  createAt      DateTime @map(\"create_at\")\n  action        String\n\n  @@map(\"ask_auditory\")\n}\n\n// ============================================================================\n// [B] MODELOS NUEVOS - agrupados por requerimiento del SRS\n// ============================================================================\n\n// ---------------------------------------------------------------------------\n// B.1 - RF-01 Autenticación / RF-02 Registro de usuarios / RNF-02 Seguridad\n// ---------------------------------------------------------------------------\n\nenum UserStatus {\n  PENDIENTE_VALIDACION\n  APROBADO\n  RECHAZADO\n}\n\n/// RF-02 - catálogo de roles (Administrador, Administrador Empresa, Usuario\n/// Delegado, Coordinador, Técnico Evaluador) usado para RBAC (RNF-02)\nmodel Role {\n  roleId      Int     @id @default(autoincrement()) @map(\"role_id\")\n  name        String  @unique\n  description String?\n\n  users User[]\n\n  @@map(\"role\")\n}\n\n/// RF-01 - Recuperación de contraseña\nmodel PasswordResetToken {\n  tokenId   Int      @id @default(autoincrement()) @map(\"token_id\")\n  userId    Int      @map(\"user_id\")\n  token     String   @unique\n  expiresAt DateTime @map(\"expires_at\")\n  used      Boolean  @default(false)\n  createdAt DateTime @default(now()) @map(\"created_at\")\n\n  user User @relation(fields: [userId], references: [userId])\n\n  @@map(\"password_reset_token\")\n}\n\n/// RF-01 - Doble factor de autenticación (opcional)\nmodel TwoFactorAuth {\n  userId  Int     @id @map(\"user_id\")\n  secret  String\n  enabled Boolean @default(false)\n\n  user User @relation(fields: [userId], references: [userId])\n\n  @@map(\"two_factor_auth\")\n}\n\n// ---------------------------------------------------------------------------\n// B.2 - Catálogos de ubicación (soporte a RF-03: Municipio / Provincia / Área de Salud)\n// ---------------------------------------------------------------------------\n\nmodel Province {\n  provinceId Int    @id @default(autoincrement()) @map(\"province_id\")\n  name       String @unique\n\n  municipalities Municipality[]\n\n  @@map(\"province\")\n}\n\nmodel Municipality {\n  municipalityId Int    @id @default(autoincrement()) @map(\"municipality_id\")\n  provinceId     Int    @map(\"province_id\")\n  name           String\n\n  province     Province      @relation(fields: [provinceId], references: [provinceId])\n  institutions Institution[]\n\n  @@map(\"municipality\")\n}\n\n/// Catálogo \"Área de Salud\" (I a VIII) visto en la Ficha BPM\nmodel HealthArea {\n  healthAreaId Int    @id @default(autoincrement()) @map(\"health_area_id\")\n  name         String @unique\n\n  @@map(\"health_area\")\n}\n\n// ---------------------------------------------------------------------------\n// B.3 - Documentos / adjuntos genéricos\n// Cubre: RF-02 (carta de autorización), RF-05 (documentación obligatoria),\n// RF-15 (evidencias), RF-16 (informe), RF-19 (informe oficial PDF)\n// ---------------------------------------------------------------------------\n\nenum AttachmentCategory {\n  CARTA_AUTORIZACION\n  DOCUMENTACION_OBLIGATORIA\n  EVIDENCIA_FOTO\n  EVIDENCIA_VIDEO\n  EVIDENCIA_DOCUMENTO\n  INFORME_ADJUNTO\n  INFORME_OFICIAL_PDF\n  OTRO\n}\n\n/// Tabla genérica de adjuntos; se relaciona opcionalmente con cada entidad\n/// que puede recibir archivos (una sola de las FKs va poblada por registro).\nmodel Attachment {\n  attachmentId Int                @id @default(autoincrement()) @map(\"attachment_id\")\n  category     AttachmentCategory\n  fileName     String             @map(\"file_name\")\n  fileUrl      String             @map(\"file_url\")\n  mimeType     String?            @map(\"mime_type\")\n  uploadedById Int?               @map(\"uploaded_by\")\n  createdAt    DateTime           @default(now()) @map(\"created_at\")\n\n  userRegistrationId Int? @map(\"user_registration_id\") // RF-02: carta de autorización\n  bpmRequestId       Int? @map(\"bpm_request_id\") // RF-05: documentación obligatoria\n  evaluationReportId Int? @map(\"evaluation_report_id\") // RF-16: fotos/documentos del informe\n  caseId             Int? @map(\"case_id\") // RF-19: informe oficial PDF\n\n  uploadedBy       User?             @relation(fields: [uploadedById], references: [userId])\n  bpmRequest       BpmRequest?       @relation(fields: [bpmRequestId], references: [bpmRequestId])\n  evaluationReport EvaluationReport? @relation(fields: [evaluationReportId], references: [reportId])\n  case             Case?             @relation(fields: [caseId], references: [caseId])\n\n  @@map(\"attachment\")\n}\n\n// ---------------------------------------------------------------------------\n// B.4 - RF-05 Solicitudes BPM\n// ---------------------------------------------------------------------------\n\nenum BpmRequestStatus {\n  BORRADOR\n  PENDIENTE_ASIGNACION\n  EN_REVISION\n  RECHAZADA\n  APROBADA\n}\n\nmodel BpmRequest {\n  bpmRequestId        Int              @id @default(autoincrement()) @map(\"bpm_request_id\")\n  institutionId       Int              @map(\"institution_id\")\n  tipoEstablecimiento String           @map(\"tipo_establecimiento\")\n  motivo              String\n  observaciones       String?\n  status              BpmRequestStatus @default(BORRADOR)\n  createdById         Int              @map(\"created_by\")\n  createdAt           DateTime         @default(now()) @map(\"created_at\")\n  sentAt              DateTime?        @map(\"sent_at\")\n\n  // vínculo opcional a la ficha diligenciada resultante (RF-12/13)\n  formResponseId Int? @unique @map(\"form_response_id\")\n\n  institution  Institution   @relation(fields: [institutionId], references: [institutionId])\n  createdBy    User          @relation(fields: [createdById], references: [userId])\n  formResponse FormResponse? @relation(fields: [formResponseId], references: [formResponseId])\n  attachments  Attachment[]\n  case         Case?\n\n  @@map(\"bpm_request\")\n}\n\n// ---------------------------------------------------------------------------\n// B.5 - RF-06 Gestión de casos / RF-19 Cierre de expediente\n// ---------------------------------------------------------------------------\n\nenum CaseOrigin {\n  SOLICITUD_EMPRESA\n  PROGRAMACION_INSTITUCIONAL\n  ALERTA_LAPCH\n  DENUNCIA\n}\n\nenum CasePriority {\n  BAJA\n  MEDIA\n  ALTA\n}\n\nenum CaseStatus {\n  ABIERTO\n  ASIGNADO\n  EN_EVALUACION\n  EN_REVISION\n  CERRADO\n}\n\n/// RF-06/RF-10/RF-19 - Expediente: unifica el origen (solicitud, programación,\n/// alerta o denuncia), la asignación de coordinador/técnico y el cierre.\nmodel Case {\n  caseId        Int          @id @default(autoincrement()) @map(\"case_id\")\n  origin        CaseOrigin\n  institutionId Int          @map(\"institution_id\")\n  priority      CasePriority @default(MEDIA)\n  status        CaseStatus   @default(ABIERTO)\n\n  coordinatorId Int? @map(\"coordinator_id\")\n  technicianId  Int? @map(\"technician_id\")\n\n  // exactamente una de estas 3 debe estar poblada según \"origin\"\n  bpmRequestId Int? @unique @map(\"bpm_request_id\")\n  lapchAlertId Int? @unique @map(\"lapch_alert_id\")\n  complaintId  Int? @unique @map(\"complaint_id\")\n\n  openedAt       DateTime  @default(now()) @map(\"opened_at\")\n  closedAt       DateTime? @map(\"closed_at\")\n  resultadoFinal String?   @map(\"resultado_final\")\n\n  institution Institution @relation(fields: [institutionId], references: [institutionId])\n  coordinator User?       @relation(\"CaseCoordinator\", fields: [coordinatorId], references: [userId])\n  technician  User?       @relation(\"CaseTechnician\", fields: [technicianId], references: [userId])\n  bpmRequest  BpmRequest? @relation(fields: [bpmRequestId], references: [bpmRequestId])\n  lapchAlert  LapchAlert? @relation(fields: [lapchAlertId], references: [alertId])\n  complaint   Complaint?  @relation(fields: [complaintId], references: [complaintId])\n\n  assignments Assignment[]\n  evaluations Evaluation[]\n  attachments Attachment[] // informe oficial PDF, etc.\n\n  @@map(\"case\")\n}\n\n// ---------------------------------------------------------------------------\n// B.6 - RF-08 Alertas LAPCH\n// ---------------------------------------------------------------------------\n\nenum LapchResult {\n  PROCEDE\n  NO_PROCEDE\n}\n\nmodel LapchAlert {\n  alertId       Int          @id @default(autoincrement()) @map(\"alert_id\")\n  numeroAlerta  String       @map(\"numero_alerta\")\n  fecha         DateTime\n  producto      String\n  institutionId Int          @map(\"institution_id\")\n  descripcion   String\n  resultado     LapchResult?\n  createdAt     DateTime     @default(now()) @map(\"created_at\")\n\n  institution Institution @relation(fields: [institutionId], references: [institutionId])\n  case        Case?\n\n  @@map(\"lapch_alert\")\n}\n\n// ---------------------------------------------------------------------------\n// B.7 - RF-09 Denuncias\n// ---------------------------------------------------------------------------\n\nenum ComplaintResult {\n  PROCEDE\n  NO_PROCEDE\n  REMISION_OTRO_PROCESO\n}\n\nmodel Complaint {\n  complaintId    Int              @id @default(autoincrement()) @map(\"complaint_id\")\n  tipoDenuncia   String           @map(\"tipo_denuncia\")\n  fechaRecepcion DateTime         @map(\"fecha_recepcion\")\n  denunciante    String\n  descripcion    String\n  resultado      ComplaintResult?\n  institutionId  Int?             @map(\"institution_id\")\n  createdAt      DateTime         @default(now()) @map(\"created_at\")\n\n  institution Institution? @relation(fields: [institutionId], references: [institutionId])\n  case        Case?\n\n  @@map(\"complaint\")\n}\n\n// ---------------------------------------------------------------------------\n// B.8 - RF-10 Asignación de evaluador (historial de asignación/reasignación)\n// ---------------------------------------------------------------------------\n\nmodel Assignment {\n  assignmentId   Int      @id @default(autoincrement()) @map(\"assignment_id\")\n  caseId         Int      @map(\"case_id\")\n  assignedToId   Int      @map(\"assigned_to\")\n  assignedById   Int      @map(\"assigned_by\")\n  isReassignment Boolean  @default(false) @map(\"is_reassignment\")\n  notes          String?\n  assignedAt     DateTime @default(now()) @map(\"assigned_at\")\n\n  case       Case @relation(fields: [caseId], references: [caseId])\n  assignedTo User @relation(\"AssignedTo\", fields: [assignedToId], references: [userId])\n  assignedBy User @relation(\"AssignedBy\", fields: [assignedById], references: [userId])\n\n  @@map(\"assignment\")\n}\n\n// ---------------------------------------------------------------------------\n// B.9 - RF-07 Programación / RF-11 Calendario / RF-12 Ejecución de evaluación\n// ---------------------------------------------------------------------------\n\nenum EvaluationStatus {\n  PROGRAMADA\n  REPROGRAMADA\n  CANCELADA\n  EN_PROCESO\n  EN_CORRECCION\n  FINALIZADA\n}\n\n/// Envuelve la ficha (FormResponse ya existente) con programación, técnico\n/// asignado y estado del proceso de campo.\nmodel Evaluation {\n  evaluationId  Int @id @default(autoincrement()) @map(\"evaluation_id\")\n  caseId        Int @map(\"case_id\")\n  institutionId Int @map(\"institution_id\")\n  technicianId  Int @map(\"technician_id\")\n\n  scheduledDate DateTime         @map(\"scheduled_date\")\n  reason        String?\n  priority      CasePriority     @default(MEDIA)\n  observations  String?\n  status        EvaluationStatus @default(PROGRAMADA)\n\n  startedAt  DateTime? @map(\"started_at\")\n  finishedAt DateTime? @map(\"finished_at\")\n\n  // ficha diligenciada (RF-12/RF-13), ya existente\n  formResponseId Int? @unique @map(\"form_response_id\")\n\n  createdAt DateTime @default(now()) @map(\"created_at\")\n\n  case         Case          @relation(fields: [caseId], references: [caseId])\n  institution  Institution   @relation(fields: [institutionId], references: [institutionId])\n  technician   User          @relation(\"EvaluationTechnician\", fields: [technicianId], references: [userId])\n  formResponse FormResponse? @relation(fields: [formResponseId], references: [formResponseId])\n\n  score     EvaluationScore?\n  evidences Evidence[]\n  report    EvaluationReport?\n\n  @@map(\"evaluation\")\n}\n\n// ---------------------------------------------------------------------------\n// B.10 - RF-14 Motor de riesgo\n// ---------------------------------------------------------------------------\n\nenum RiskLevel {\n  BAJO\n  MEDIO\n  ALTO\n}\n\nenum InspectionFrequency {\n  ANUAL\n  SEMESTRAL\n  TRIMESTRAL\n}\n\n/// Tabla de referencia estática = \"Matriz de Frecuencia de Inspección\" del SRS\n/// (1.0-3.6 => Bajo/Anual, >3.6-6.3 => Medio/Semestral, >6.3 => Alto/Trimestral)\nmodel RiskFrequencyRule {\n  ruleId    Int                 @id @default(autoincrement()) @map(\"rule_id\")\n  minScore  Float               @map(\"min_score\")\n  maxScore  Float?              @map(\"max_score\")\n  riskLevel RiskLevel           @map(\"risk_level\")\n  frequency InspectionFrequency\n\n  @@map(\"risk_frequency_rule\")\n}\n\n/// Resultado calculado automáticamente por evaluación (puntaje, % cumplimiento, nivel)\nmodel EvaluationScore {\n  evaluationId           Int                 @id @map(\"evaluation_id\")\n  puntajeObtenido        Float               @map(\"puntaje_obtenido\")\n  porcentajeCumplimiento Float               @map(\"porcentaje_cumplimiento\")\n  nivelRiesgo            RiskLevel           @map(\"nivel_riesgo\")\n  frecuenciaInspeccion   InspectionFrequency @map(\"frecuencia_inspeccion\")\n  calculatedAt           DateTime            @default(now()) @map(\"calculated_at\")\n\n  evaluation Evaluation @relation(fields: [evaluationId], references: [evaluationId])\n\n  @@map(\"evaluation_score\")\n}\n\n// ---------------------------------------------------------------------------\n// B.11 - RF-15 Captura de evidencias\n// ---------------------------------------------------------------------------\n\nenum EvidenceType {\n  FOTO\n  VIDEO\n  DOCUMENTO\n}\n\nmodel Evidence {\n  evidenceId   Int          @id @default(autoincrement()) @map(\"evidence_id\")\n  evaluationId Int          @map(\"evaluation_id\")\n  type         EvidenceType\n  fileUrl      String       @map(\"file_url\")\n  latitude     Float?\n  longitude    Float?\n  comment      String?\n  capturedAt   DateTime     @default(now()) @map(\"captured_at\")\n\n  // referencia opcional a la pregunta específica de la ficha (h1..h4 ask)\n  h1AskId Int? @map(\"h1_ask_id\")\n  h2AskId Int? @map(\"h2_ask_id\")\n  h3AskId Int? @map(\"h3_ask_id\")\n  h4AskId Int? @map(\"h4_ask_id\")\n\n  evaluation Evaluation @relation(fields: [evaluationId], references: [evaluationId])\n\n  @@map(\"evidence\")\n}\n\n// ---------------------------------------------------------------------------\n// B.12 - RF-16 Informe / RF-17 Revisión del coordinador / RF-18 Correcciones\n// ---------------------------------------------------------------------------\n\nenum ReportStatus {\n  BORRADOR\n  ENVIADO\n  APROBADO\n  DEVUELTO\n  EN_CORRECCION\n}\n\nenum CorrectionScope {\n  PARCIAL\n  COMPLETA\n}\n\n/// RF-16 - Informe generado automáticamente a partir de la evaluación\nmodel EvaluationReport {\n  reportId         Int          @id @default(autoincrement()) @map(\"report_id\")\n  evaluationId     Int          @unique @map(\"evaluation_id\")\n  resumenEjecutivo String       @map(\"resumen_ejecutivo\")\n  hallazgos        String\n  noConformidades  String       @map(\"no_conformidades\")\n  recomendaciones  String\n  status           ReportStatus @default(BORRADOR)\n  version          Int          @default(1) // se incrementa en cada corrección (RF-18)\n  locked           Boolean      @default(false) // RF-17: se bloquea tras enviarse\n  generatedAt      DateTime     @default(now()) @map(\"generated_at\")\n\n  /// Open correction request. Cleared when the same report is resubmitted.\n  correctionScope       CorrectionScope? @map(\"correction_scope\")\n  flaggedSections       Json?            @map(\"flagged_sections\")\n  correctionRequestedAt DateTime?        @map(\"correction_requested_at\")\n  correctionSavedAt     DateTime?        @map(\"correction_saved_at\")\n\n  /// Last narrative produced from the answers. Matching fields stay in sync\n  /// with the field record; a hand-edited field is left as the inspector saved it.\n  autoNarrative Json? @map(\"auto_narrative\")\n\n  evaluation  Evaluation     @relation(fields: [evaluationId], references: [evaluationId])\n  attachments Attachment[]\n  reviews     ReportReview[]\n\n  @@map(\"evaluation_report\")\n}\n\nenum ReviewAction {\n  APROBAR\n  DEVOLVER\n  SOLICITAR_CORRECCION\n}\n\n/// RF-17/RF-18 - Cada acción del coordinador sobre un informe (y su posterior\n/// corrección/reenvío por parte del técnico)\nmodel ReportReview {\n  reviewId        Int              @id @default(autoincrement()) @map(\"review_id\")\n  reportId        Int              @map(\"report_id\")\n  coordinatorId   Int              @map(\"coordinator_id\")\n  action          ReviewAction\n  comments        String?\n  correctionScope CorrectionScope? @map(\"correction_scope\")\n  flaggedSections Json?            @map(\"flagged_sections\")\n  reviewedAt      DateTime         @default(now()) @map(\"reviewed_at\")\n\n  report      EvaluationReport @relation(fields: [reportId], references: [reportId])\n  coordinator User             @relation(fields: [coordinatorId], references: [userId])\n\n  @@map(\"report_review\")\n}\n\n// ---------------------------------------------------------------------------\n// B.13 - RF-04 Notificaciones (dashboards)\n// ---------------------------------------------------------------------------\n\nmodel Notification {\n  notificationId Int      @id @default(autoincrement()) @map(\"notification_id\")\n  userId         Int      @map(\"user_id\")\n  title          String\n  message        String\n  read           Boolean  @default(false)\n  createdAt      DateTime @default(now()) @map(\"created_at\")\n\n  user User @relation(fields: [userId], references: [userId])\n\n  @@map(\"notification\")\n}\n\n// ---------------------------------------------------------------------------\n// B.14 - RepresentType (apoyo a B.2 / Institution.Represent)\n// ---------------------------------------------------------------------------\n\nenum RepresentType {\n  LEGAL\n  CALIDAD\n  CONTACTO\n}\n"
}

